export type FieldType = 'text' | 'number' | 'select' | 'date' | 'checkbox';
export interface NamedRule {
  name: string;
  value: number | null;
}
export interface FieldRules {
  type: FieldType;
  required: boolean;
  min: number | null;
  max: number | null;
  pattern: string | null;
  validators: NamedRule[];
}
export type FieldValue = string | boolean;
export interface ValidationContext {
  legalAge: number;
  today: Date;
}
export const INVALID_ERROR = 'invalid';

import { ValidationContext } from './validation.model';

export type NamedRuleFactory = (
  value: number | null,
  ctx: ValidationContext,
) => (raw: string) => boolean;

/** Chilean RUT check-digit validation (modulo 11). */
export function isValidRut(raw: string): boolean {
  const clean = raw.replace(/[.\s-]/g, '').toUpperCase();
  const match = /^(\d{7,8})([0-9K])$/.exec(clean);
  if (!match) return false;
  const body = match[1];
  let sum = 0;
  let weight = 2;
  for (let i = body.length - 1; i >= 0; i--) {
    sum += Number(body[i]) * weight;
    weight = weight === 7 ? 2 : weight + 1;
  }
  const rest = 11 - (sum % 11);
  const expected = rest === 11 ? '0' : rest === 10 ? 'K' : String(rest);
  return match[2] === expected;
}

/** raw is yyyy-mm-dd; age computed from local date components. */
export function isOfLegalAge(raw: string, legalAge: number, today: Date): boolean {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(raw);
  if (!match) return false;
  const y = Number(match[1]);
  const m = Number(match[2]);
  const d = Number(match[3]);
  const birth = new Date(y, m - 1, d);
  if (birth.getFullYear() !== y || birth.getMonth() !== m - 1 || birth.getDate() !== d) {
    return false;
  }
  const t = new Date(today.getFullYear(), today.getMonth(), today.getDate());
  if (birth.getTime() > t.getTime()) return false;
  let age = t.getFullYear() - y;
  if (t.getMonth() + 1 < m || (t.getMonth() + 1 === m && t.getDate() < d)) age--;
  return age >= legalAge;
}

function parseYear(raw: string): number | null {
  const s = raw.trim();
  return /^\d{1,4}$/.test(s) ? Number(s) : null;
}

export const NAMED_RULES: Record<string, NamedRuleFactory> = {
  rut: () => (raw) => isValidRut(raw),
  legalAge: (_value, ctx) => (raw) => isOfLegalAge(raw, ctx.legalAge, ctx.today),
  maxYearsAgo: (value, ctx) => (raw) => {
    const year = parseYear(raw);
    return year !== null && value !== null && year >= ctx.today.getFullYear() - value;
  },
  maxYearsAhead: (value, ctx) => (raw) => {
    const year = parseYear(raw);
    return year !== null && value !== null && year <= ctx.today.getFullYear() + value;
  },
};

import { ValidatorFn } from '@angular/forms';
import { NAMED_RULES } from './named-rules';
import { FieldRules, INVALID_ERROR, ValidationContext } from './validation.model';

const FAIL = { [INVALID_ERROR]: true };

function isEmpty(value: unknown): boolean {
  return value === null || value === undefined || (typeof value === 'string' && value.trim() === '');
}

export function buildValidators(
  rules: FieldRules,
  ctx: ValidationContext,
  fieldKey: string,
): ValidatorFn[] {
  const validators: ValidatorFn[] = [];

  if (rules.required) {
    validators.push((c) => {
      const v: unknown = c.value;
      if (rules.type === 'checkbox') return v === true ? null : FAIL;
      return isEmpty(v) || v === false ? FAIL : null;
    });
  }

  if (rules.type === 'number' && (rules.min !== null || rules.max !== null)) {
    validators.push((c) => {
      const v: unknown = c.value;
      if (isEmpty(v)) return null;
      const n = Number(String(v).trim());
      if (!Number.isFinite(n)) return FAIL;
      if (rules.min !== null && n < rules.min) return FAIL;
      if (rules.max !== null && n > rules.max) return FAIL;
      return null;
    });
  }

  if (rules.pattern) {
    try {
      const re = new RegExp(`^(?:${rules.pattern})$`);
      validators.push((c) => {
        const v: unknown = c.value;
        if (isEmpty(v)) return null;
        return re.test(String(v)) ? null : FAIL;
      });
    } catch {
      console.warn(`[form] Invalid pattern on field "${fieldKey}" – skipped`);
    }
  }

  for (const rule of rules.validators) {
    const factory = NAMED_RULES[rule.name];
    if (!factory) {
      console.warn(`[form] Unknown rule "${rule.name}" on field "${fieldKey}" – skipped`);
      continue;
    }
    const check = factory(rule.value, ctx);
    validators.push((c) => {
      const v: unknown = c.value;
      if (isEmpty(v) || typeof v !== 'string') return null;
      return check(v) ? null : FAIL;
    });
  }

  return validators;
}

import { describe, expect, it } from 'vitest';
import { NAMED_RULES } from './named-rules';
import { ValidationContext } from './validation.model';

const ctx = (legalAge: number, today = new Date(2026, 10, 22)): ValidationContext => ({
  legalAge,
  today,
});

describe('US-01 · FR-014 RUT check digit', () => {
  const rut = NAMED_RULES['rut'](null, ctx(18));
  it.each(['12.345.678-5', '12345678-5', '123456785', '7.654.321-6', '1.000.005-K', '1.000.005-k'])(
    'accepts %s',
    (v) => expect(rut(v)).toBe(true),
  );
  it.each(['12.345.678-9', '1234A678-5', '123456-5', '1.000.005-1', ''])('rejects "%s"', (v) =>
    expect(rut(v)).toBe(false),
  );
});

describe('US-01 · FR-007 legal age', () => {
  const today = new Date(2026, 10, 22);
  const rule18 = NAMED_RULES['legalAge'](null, ctx(18, today));
  it('valid when turning 18 today', () => expect(rule18('2008-11-22')).toBe(true));
  it('invalid when turning 18 tomorrow', () => expect(rule18('2008-11-23')).toBe(false));
  it('invalid for future date', () => expect(rule18('2030-01-01')).toBe(false));
  it('invalid for malformed or impossible date', () => {
    expect(rule18('abc')).toBe(false);
    expect(rule18('2000-02-31')).toBe(false);
  });
  it('uses the country legal age (21)', () => {
    const rule21 = NAMED_RULES['legalAge'](null, ctx(21, today));
    expect(rule21('2006-11-22')).toBe(false);
    expect(rule21('2005-11-22')).toBe(true);
  });
});

describe('US-01 · FR-008 year range rules', () => {
  const ago = NAMED_RULES['maxYearsAgo'](20, ctx(18));
  const ahead = NAMED_RULES['maxYearsAhead'](1, ctx(18));
  it.each([
    ['2006', true],
    ['2005', false],
    ['20.5', false],
    ['abc', false],
  ] as const)('maxYearsAgo 20: %s -> %s', (v, ok) => expect(ago(v)).toBe(ok));
  it.each([
    ['2027', true],
    ['2028', false],
    ['20.5', false],
    ['abc', false],
  ] as const)('maxYearsAhead 1: %s -> %s', (v, ok) => expect(ahead(v)).toBe(ok));
});

